// Verifies the HMAC Convex put on this request: sha256 over `${timestamp}.${rawBody}`.
const crypto = require("crypto");
const secret = $env.CONVEX_TO_N8N_SECRET;
const item = $input.first();
const headers = item.json.headers || {};
const timestamp = String(headers["x-lendloop-timestamp"] || "");
const signature = String(headers["x-lendloop-signature"] || "").replace(/^sha256=/, "");

// Use the raw bytes when n8n kept them, so the HMAC covers exactly what was sent.
let raw;
if (item.binary && item.binary.data) {
  raw = (await this.helpers.getBinaryDataBuffer(0, "data")).toString("utf8");
} else {
  raw = JSON.stringify(item.json.body);
}

const fresh = /^\d{10}$/.test(timestamp) && Math.abs(Date.now() / 1000 - Number(timestamp)) <= 300;
let valid = false;
if (secret && fresh && /^[0-9a-f]{64}$/.test(signature)) {
  const expected = crypto.createHmac("sha256", secret).update(`${timestamp}.${raw}`).digest("hex");
  valid = crypto.timingSafeEqual(Buffer.from(expected, "hex"), Buffer.from(signature, "hex"));
}
if (!valid) return [{ json: { valid: false } }];

// Keep only the fields the message needs. Nothing else travels further in this run.
const event = JSON.parse(raw);
return [
  {
    json: {
      valid: true,
      eventId: event.eventId,
      type: event.type,
      recipient: event.recipient,
      counterpart: event.counterpart,
      tool: event.tool,
      loan: event.loan,
      link: event.link,
    },
  },
];

// Convex retries until it gets a 2xx. If an earlier attempt sent the email but the
// response was lost, the same eventId arrives again: answer 200 without re-sending.
const store = $getWorkflowStaticData("global");
const processed = store.processed || {};
const event = $input.first().json;
return [{ json: { ...event, duplicate: Boolean(processed[event.eventId]) } }];

const e = $input.first().json;
const who = e.counterpart.firstName;
const tool = e.tool.name;
const dates = e.loan.startDate === e.loan.endDate ? e.loan.startDate : `${e.loan.startDate} to ${e.loan.endDate}`;
const link = e.link ? `\n\nOpen LendLoop: ${e.link}` : "";
const templates = {
  "loan.requested": [`${who} wants to borrow your ${tool}`, `${who} asked to borrow your ${tool} for ${dates}. Approve or decline the request in LendLoop.`],
  "loan.approved": [`${who} approved your request for the ${tool}`, `Good news: ${who} approved your request for the ${tool} for ${dates}.`],
  "loan.declined": [`Your request for the ${tool} was declined`, `Your request to borrow the ${tool} for ${dates} was declined. Other tools are waiting in LendLoop.`],
  "loan.cancelled": [`${who} cancelled a request for your ${tool}`, `${who} cancelled their request to borrow your ${tool} for ${dates}.`],
  "loan.returned": [`${who} confirmed the ${tool} is back`, `${who} marked the ${tool} as returned. Thanks for bringing it back.`],
};
const [subject, body] = templates[e.type] || [`Update on the ${tool}`, `There is an update on your loan of the ${tool}.`];
return [
  {
    json: {
      eventId: e.eventId,
      to: e.recipient.email,
      subject,
      text: `Hi ${e.recipient.firstName},\n\n${body}${link}\n\nLendLoop`,
    },
  },
];

const store = $getWorkflowStaticData("global");
const processed = store.processed || {};
const eventId = $("Compose message").first().json.eventId;
processed[eventId] = Date.now();
// Keep a week of history so the store stays small.
const weekAgo = Date.now() - 7 * 24 * 3600 * 1000;
for (const [id, at] of Object.entries(processed)) if (at < weekAgo) delete processed[id];
store.processed = processed;
return [{ json: { delivered: true, eventId } }];
